import figlet from "figlet"
import * as fs from "node:fs"
import * as path from "node:path"

const text = "TermiWallet"
const font: figlet.Fonts = "Small"

const raw = figlet.textSync(text, { font })
// Trim trailing empty line if present, but preserve leading indentations
const lines = raw.split("\n")
while (lines.length > 0 && lines[lines.length - 1].trim() === "") {
  lines.pop()
}

const bannerConstant = lines.join("\n")

const targetPath = path.resolve(import.meta.dir, "../src/ui/components/LogoBanner.tsx")

const fileContent = `/**
 * Generated by scripts/generate-logo.ts using FIGlet (font: "${font}")
 * Run \`bun run generate:logo\` to regenerate.
 */

export const TERMIWALLET_ASCII_BANNER = ${JSON.stringify(bannerConstant)}

interface LogoBannerProps {
  color?: string
  subtitle?: string
  description?: string
}

export function LogoBanner({
  color = "#60A5FA",
  subtitle,
  description,
}: LogoBannerProps) {
  return (
    <box
      style={{
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        marginBottom: 1,
      }}
    >
      <text fg={color}>
        <b>{TERMIWALLET_ASCII_BANNER}</b>
      </text>
      {subtitle ? (
        <box style={{ marginTop: 1, alignItems: "center" }}>
          <text fg="#60A5FA">
            <b>{subtitle}</b>
          </text>
        </box>
      ) : null}
      {description ? (
        <box style={{ marginTop: subtitle ? 0 : 1, alignItems: "center" }}>
          <text fg="#D1D5DB">{description}</text>
        </box>
      ) : null}
    </box>
  )
}
`

fs.writeFileSync(targetPath, fileContent, "utf-8")
console.log(`Successfully generated LogoBanner.tsx at ${targetPath}`)
